import{_ as a,o as e,c as s,a0 as d}from"./chunks/framework.DQOulFGV.js";const k=JSON.parse('{"title":"GNU Screen 使用文档","description":"","frontmatter":{},"headers":[],"relativePath":"tools/screen.md","filePath":"tools/screen.md","lastUpdated":1786584773000}'),r={name:"tools/screen.md"};function i(n,t,o,l,h,c){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="gnu-screen-使用文档" tabindex="-1">GNU Screen 使用文档 <a class="header-anchor" href="#gnu-screen-使用文档" aria-label="Permalink to &quot;GNU Screen 使用文档&quot;">​</a></h1><blockquote><p><strong>GNU Screen</strong> 是一款终端多路复用工具，允许在单个终端窗口中运行多个会话，断开连接后程序仍可后台运行，适用于远程服务器运维和长时间任务管理。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#session">1. 会话管理</a></li><li><a href="#window">2. 窗口操作</a></li><li><a href="#split">3. 分屏操作</a></li><li><a href="#copy">4. 复制与滚动</a></li><li><a href="#tips">5. 实用技巧</a></li></ul><hr><h2 id="session" tabindex="-1">1. 会话管理 <a class="header-anchor" href="#session" aria-label="Permalink to &quot;1. 会话管理 {#session}&quot;">​</a></h2><h3 id="_1-1-创建会话" tabindex="-1">1.1 创建会话 <a class="header-anchor" href="#_1-1-创建会话" aria-label="Permalink to &quot;1.1 创建会话&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 创建匿名会话</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">screen</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 创建命名会话（推荐）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">screen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp</span></span></code></pre></div><h3 id="_1-2-查看与恢复" tabindex="-1">1.2 查看与恢复 <a class="header-anchor" href="#_1-2-查看与恢复" aria-label="Permalink to &quot;1.2 查看与恢复&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 列出所有会话</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">screen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ls</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 恢复指定会话</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">screen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 恢复唯一会话</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">screen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 先分离再恢复（会话被占用时）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">screen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp</span></span></code></pre></div><h3 id="_1-3-分离与终止" tabindex="-1">1.3 分离与终止 <a class="header-anchor" href="#_1-3-分离与终止" aria-label="Permalink to &quot;1.3 分离与终止&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>命令</th></tr></thead><tbody><tr><td><strong>分离当前会话</strong></td><td>快捷键 <code>Ctrl+a d</code> 或 <code>screen -d myapp</code></td></tr><tr><td><strong>杀死指定会话</strong></td><td><code>screen -X -S myapp quit</code></td></tr><tr><td><strong>清理僵尸会话</strong></td><td><code>screen -wipe</code></td></tr></tbody></table><hr><h2 id="window" tabindex="-1">2. 窗口操作 <a class="header-anchor" href="#window" aria-label="Permalink to &quot;2. 窗口操作 {#window}&quot;">​</a></h2><blockquote><p>所有会话内快捷键均以 <code>Ctrl+a</code> 为前缀。</p></blockquote><table tabindex="0"><thead><tr><th>快捷键</th><th>说明</th></tr></thead><tbody><tr><td><code>Ctrl+a c</code></td><td>新建窗口</td></tr><tr><td><code>Ctrl+a n</code></td><td>切换到下一个窗口</td></tr><tr><td><code>Ctrl+a p</code></td><td>切换到上一个窗口</td></tr><tr><td><code>Ctrl+a &quot;</code></td><td>列出所有窗口，交互式选择</td></tr><tr><td><code>Ctrl+a A</code></td><td>重命名当前窗口</td></tr><tr><td><code>Ctrl+a k</code></td><td>关闭当前窗口</td></tr><tr><td><code>Ctrl+a ?</code></td><td>显示帮助（快捷键列表）</td></tr></tbody></table><hr><h2 id="split" tabindex="-1">3. 分屏操作 <a class="header-anchor" href="#split" aria-label="Permalink to &quot;3. 分屏操作 {#split}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>说明</th></tr></thead><tbody><tr><td><code>Ctrl+a S</code></td><td>水平分屏</td></tr><tr><td><code>Ctrl+a |</code></td><td>垂直分屏</td></tr><tr><td><code>Ctrl+a Tab</code></td><td>切换分屏区域</td></tr><tr><td><code>Ctrl+a X</code></td><td>关闭当前分屏区域</td></tr></tbody></table><p>分屏后新区域为空白，需按 <code>Ctrl+a c</code> 创建窗口或 <code>Ctrl+a &quot;</code> 选择已有窗口。</p><hr><h2 id="copy" tabindex="-1">4. 复制与滚动 <a class="header-anchor" href="#copy" aria-label="Permalink to &quot;4. 复制与滚动 {#copy}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>说明</th></tr></thead><tbody><tr><td><code>Ctrl+a [</code></td><td>进入复制/滚动模式（方向键或 <code>PgUp</code>/<code>PgDn</code> 翻看历史，<code>q</code> 退出）</td></tr><tr><td><code>Ctrl+a ]</code></td><td>粘贴复制的内容</td></tr></tbody></table><p>复制模式下按 <code>Space</code> 开始选择，移动光标后再按 <code>Space</code> 完成复制。</p><hr><h2 id="tips" tabindex="-1">5. 实用技巧 <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;5. 实用技巧 {#tips}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td><strong>命名规范</strong></td><td>始终使用 <code>screen -S name</code> 创建命名会话，便于识别和管理</td></tr><tr><td><strong>日志记录</strong></td><td><code>Ctrl+a H</code> 开启日志记录，输出保存到 <code>screenlog.N</code> 文件</td></tr><tr><td><strong>配置文件</strong></td><td>自定义 <code>~/.screenrc</code> 设置默认行为，如状态栏、滚动缓冲区大小</td></tr><tr><td><strong>滚动缓冲</strong></td><td>在 <code>~/.screenrc</code> 中添加 <code>defscrollback 10000</code> 增大历史缓冲行数</td></tr><tr><td><strong>状态栏</strong></td><td>在 <code>~/.screenrc</code> 中添加 <code>hardstatus alwayslastline &quot;%w&quot;</code> 显示窗口列表</td></tr><tr><td><strong>替代方案</strong></td><td>如需更现代的功能（如鼠标支持、窗格布局），可考虑 <code>tmux</code></td></tr></tbody></table>`,28)])])}const b=a(r,[["render",i]]);export{k as __pageData,b as default};
